/* NAMED (Nov 25 2026, LR-4): on a phone the 440 px boombox is drawn smaller to fit the screen (the factor the page's
   script sets, --bbx-pop-fit, at most 1), and its layout box shrinks with it, so nothing scrolls sideways. The
   desktop window is unchanged: every rule is inside this media query. */
@media (max-width: 760px){
  #bfMusicPopout{width:100%;max-width:100%;display:flex;justify-content:center}
  #bfMusicPopout .bfm-pop{width:100%;min-width:0}
  #bfMusicPopout .bfm-pop .bbx{transform:scale(var(--bbx-pop-fit, 1));transform-origin:top center;margin:0 calc((var(--bbx-pop-fit, 1) - 1) * 220px) calc((var(--bbx-pop-fit, 1) - 1) * 250px)}
  #bfMusicPopout .bfm-pop .bfm-drawer{width:100%;max-width:100%}
}
